// ------------------------------------------------------------------
//     Offline Supabase client – localStorage, fully thenable
// ------------------------------------------------------------------

const genID = () => Date.now().toString(36) + Math.random().toString(36).slice(2);

function load(table) {
  try {
    const data = localStorage.getItem('bwanali_' + table);
    return data ? JSON.parse(data) : [];
  } catch { return []; }
}
function save(table, rows) {
  localStorage.setItem('bwanali_' + table, JSON.stringify(rows));
}

// Seed demo data on first load
if (!localStorage.getItem('bwanali_seeded')) {
  save('stores', [{
    id: 'store-1', name: 'Demo Store', subscription_status: 'trialing',
    trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false
  }]);
  save('staff', [{
    id: 'staff-1', store_id: 'store-1', full_name: 'Admin Demo',
    email: 'admin@demo.com', role: 'admin', pin_code: '1234', is_active: true
  }]);
  save('products', [
    { id: 'prod-1', store_id: 'store-1', name: 'Cooking Oil 2L', barcode: '111', category: 'Groceries', unit_price: 230, cost_price: 210, stock_quantity: 20, is_active: true },
    { id: 'prod-2', store_id: 'store-1', name: 'Sugar 1kg', barcode: '222', category: 'Groceries', unit_price: 38, cost_price: 30, stock_quantity: 100, is_active: true },
    { id: 'prod-3', store_id: 'store-1', name: 'Bread Loaf', barcode: '333', category: 'Bakery', unit_price: 25, cost_price: 18, stock_quantity: 50, is_active: true },
  ]);
  save('company_settings', [{
    id: 'settings-1', store_id: 'store-1', company_name: 'Demo Store Ltd',
    local_currency: 'ZMW', receipt_footer: 'Thank you!'
  }]);
  save('customers', []);
  save('sales', []);
  save('sale_items', []);
  save('cash_shifts', []);
  save('discount_rules', []);
  save('returns', []);
  save('laybys', []);
  save('store_admins', []);
  localStorage.setItem('bwanali_seeded', '1');
}

// ------------------------------------------------------------------
// Helper: make any value a `thenable` with `.catch`
// ------------------------------------------------------------------
function makeThenable(value) {
  if (value === undefined || value === null) return makeThenable({});
  if (typeof value.then === 'function') {
    if (!value.catch) value.catch = () => value;
    return value;
  }
  // plain object
  return {
    ...value,
    then: (resolve) => resolve(value),
    catch: (fn) => makeThenable(value), // ignore rejections
  };
}

// ------------------------------------------------------------------
// Query builder – builds up filters, then executes when needed
// ------------------------------------------------------------------
function createQuery(table) {
  const filters = [];
  let action = null;          // 'select', 'insert', 'update', 'delete', 'upsert'
  let dataPayload = null;
  let limitNum = null;
  let singleMode = false;
  let countMode = false, headOnly = false;
  let orderBy = null, orderAsc = true;

  const apply = () => {
    let rows = load(table);
    filters.forEach(f => {
      try {
        if (f.type === 'eq')      rows = rows.filter(r => r[f.col] === f.val);
        else if (f.type === 'gte') rows = rows.filter(r => new Date(r[f.col]) >= new Date(f.val));
        else if (f.type === 'lte') rows = rows.filter(r => new Date(r[f.col]) <= new Date(f.val));
        else if (f.type === 'not') rows = rows.filter(r => r[f.col] !== f.val);
        else if (f.type === 'is')  rows = rows.filter(r => r[f.col] === null);
      } catch {}
    });
    if (orderBy) {
      rows.sort((a, b) => (a[orderBy] > b[orderBy] ? 1 : -1) * (orderAsc ? 1 : -1));
    }
    return rows;
  };

  // ----- Execute the built‑up query -----
  const execute = () => {
    if (action === 'select') {
      const list = apply();
      let resultList = list;
      if (limitNum !== null) resultList = list.slice(0, limitNum);
      if (singleMode) {
        return makeThenable({ data: list[0] || null, error: null });
      }
      if (countMode) {
        return makeThenable({ count: headOnly ? list.length : apply().length, data: headOnly ? [] : resultList, error: null });
      }
      return makeThenable({ data: resultList, error: null });
    }

    if (action === 'insert') {
      const arr = Array.isArray(dataPayload) ? dataPayload : [dataPayload];
      const newRows = arr.map(d => ({ id: genID(), ...d }));
      const cur = load(table);
      save(table, [...cur, ...newRows]);
      // Return an object that also supports `.select().single()` as real Supabase does
      const result = makeThenable({ data: newRows, error: null });
      result.select = () => makeThenable({ data: newRows, error: null });
      result.single = () => makeThenable({ data: newRows[0] || null, error: null });
      return result;
    }

    if (action === 'update') {
      try {
        const cur = load(table);
        const updated = cur.map(r => {
          const match = filters.every(f => r[f.col] === f.val);
          return match ? { ...r, ...dataPayload } : r;
        });
        save(table, updated);
        return makeThenable({ error: null });
      } catch (e) { return makeThenable({ error: { message: e.message } }); }
    }

    if (action === 'delete') {
      try {
        const cur = load(table);
        const remaining = cur.filter(r => !filters.every(f => r[f.col] === f.val));
        save(table, remaining);
        return makeThenable({ error: null });
      } catch (e) { return makeThenable({ error: { message: e.message } }); }
    }

    if (action === 'upsert') {
      const cur = load(table);
      const arr = Array.isArray(dataPayload) ? dataPayload : [dataPayload];
      arr.forEach(d => {
        const idx = cur.findIndex(r => r.id === d.id);
        if (idx >= 0) cur[idx] = d;
        else cur.push({ id: genID(), ...d });
      });
      save(table, cur);
      return makeThenable({ error: null });
    }

    return makeThenable({ error: { message: 'No query action defined' } });
  };

  // ----- Proxy – intercepts method calls to build context -----
  const proxy = new Proxy({}, {
    get(target, prop) {
      // Terminal methods – execute and return thenable
      if (prop === 'then') return (resolve, reject) => resolve(execute());
      if (prop === 'catch') return (fn) => proxy; // ignore

      // Methods that set action
      if (prop === 'select') return (...args) => {
        action = 'select';
        if (args[1] && args[1].count === 'exact') {
          countMode = true;
          if (args[1].head) headOnly = true;
        }
        return proxy;
      };
      if (prop === 'insert') return (data) => {
        action = 'insert';
        dataPayload = data;
        return execute(); // insert directly returns result
      };
      if (prop === 'update') return (data) => {
        action = 'update';
        dataPayload = data;
        return proxy; // wait for .eq() / .in()
      };
      if (prop === 'delete') return () => {
        action = 'delete';
        return proxy; // wait for .eq()
      };
      if (prop === 'upsert') return (data) => {
        action = 'upsert';
        dataPayload = data;
        return execute();
      };
      if (prop === 'eq') return (col, val) => { filters.push({ type: 'eq', col, val }); return proxy; };
      if (prop === 'gte') return (col, val) => { filters.push({ type: 'gte', col, val }); return proxy; };
      if (prop === 'lte') return (col, val) => { filters.push({ type: 'lte', col, val }); return proxy; };
      if (prop === 'not') return (col, val) => { filters.push({ type: 'not', col, val }); return proxy; };
      if (prop === 'is') return (col, val) => { filters.push({ type: 'is', col, val }); return proxy; };
      if (prop === 'order') return (col, opt) => {
        orderBy = col;
        orderAsc = opt?.ascending !== false;
        return execute(); // order usually ends the chain
      };
      if (prop === 'limit') return (n) => {
        limitNum = n;
        return execute();
      };
      if (prop === 'single' || prop === 'maybeSingle') {
        singleMode = true;
        return execute();
      }
      if (prop === 'in') return (col, vals) => {
        // For .in(), we add a filter that checks if the value is in the array
        filters.push({ type: 'in', col, vals });
        return proxy;
      };

      // For any other property, just return a function that returns the proxy
      return () => proxy;
    }
  });

  return proxy;
}

// ------------------------------------------------------------------
// Auth helpers (local)
// ------------------------------------------------------------------
function getStoredUser() {
  const raw = localStorage.getItem('local_user');
  return raw ? JSON.parse(raw) : null;
}

// ------------------------------------------------------------------
// The exported fake supabase object
// ------------------------------------------------------------------
export const supabase = {
  from: (table) => createQuery(table),

  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = load('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = getStoredUser();
      return { data: { session: user ? { user, access_token: 'offline', refresh_token: 'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = getStoredUser();
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = load('staff');
      const newUser = { id: genID(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      save('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },

  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },

  rpc: () => makeThenable({ error: null }),
};
